  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 50);
  assert.equal(totals.discount, 50);
  assert.equal(totals.total, 0);
});

test('addLine with discountPercent', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
